mapper.select:
SELECT 
FROM project p JOIN project_member m ON m.project_id = p.business_id
AND m.tenant_id = p.tenant_id
WHERE p.tenant_id = #{tenantId} AND p.business_id = #{projectId}
AND m.user_id = #{userId}

SELECT role FROM project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}

SELECT user_id, role FROM project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
ORDER BY user_id

SELECT expert_id, enabled FROM project_expert
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
ORDER BY expert_id

SELECT COUNT(*) FROM project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}

mapper.update:
UPDATE project_member SET role = #{role}, updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}

mapper.delete:
DELETE FROM project_member
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND user_id = #{userId}

mapper.select:
